class FrequencyTracker {
    std::unordered_map<int, int> num_freq;
    std::unordered_map<int, int> freq_count;
public:
    FrequencyTracker() {}

    void add(int number) {
        int old_f = num_freq[number];
        if (old_f > 0) freq_count[old_f]--;
        int new_f = old_f + 1;
        num_freq[number] = new_f;
        freq_count[new_f]++;
    }

    void deleteOne(int number) {
        int old_f = num_freq[number];
        if (old_f == 0) return;
        freq_count[old_f]--;
        int new_f = old_f - 1;
        num_freq[number] = new_f;
        if (new_f > 0) freq_count[new_f]++;
    }

    bool hasFrequency(int frequency) {
        return freq_count[frequency] > 0;
    }
};

class FrequencyTracker {
    private final Map<Integer, Integer> numFreq = new HashMap<>();
    private final Map<Integer, Integer> freqCount = new HashMap<>();

    public FrequencyTracker() {}

    public void add(int number) {
        int oldF = numFreq.getOrDefault(number, 0);
        if (oldF > 0) freqCount.put(oldF, freqCount.get(oldF) - 1);
        int newF = oldF + 1;
        numFreq.put(number, newF);
        freqCount.put(newF, freqCount.getOrDefault(newF, 0) + 1);
    }

    public void deleteOne(int number) {
        int oldF = numFreq.getOrDefault(number, 0);
        if (oldF == 0) return;
        freqCount.put(oldF, freqCount.get(oldF) - 1);
        int newF = oldF - 1;
        numFreq.put(number, newF);
        if (newF > 0) freqCount.put(newF, freqCount.getOrDefault(newF, 0) + 1);
    }

    public boolean hasFrequency(int frequency) {
        return freqCount.getOrDefault(frequency, 0) > 0;
    }
}

